"""The rows between the words: notices, dividers, compactions, command output, the turn's footer,
the working line, the loading skeleton."""

from __future__ import annotations

import html
import random
import re
import time
from typing import Any, Callable, Optional, Tuple

from PySide6.QtCore import QPointF, QRect, QRectF, Qt
from PySide6.QtGui import QColor, QPainter

from ... import theme
from ...lib.fmt import cost, duration, tokens
from ...lib.transcript_model import CommandOutputItem, CompactItem, NoticeItem, ResultItem
from ...store import store
from .. import nodes as nd
from ..paint import Measurer, PaintState, rounded
from ..pixels import hline
from ..scene import Block, Target
from .base import NodeBlock

VERBS = [
    "Reading",
    "Drafting",
    "Composing",
    "Outlining",
    "Revising",
    "Proofing",
    "Collating",
    "Annotating",
    "Indexing",
    "Marking up",
    "Typesetting",
    "Kerning",
]


# ---------------------------------------------------------------- dividers


class DividerBlock(Block):
    """A centred line of micro text with hairlines either side."""

    KIND = "divider"
    __slots__ = ("label",)

    def __init__(self, key: str, label: str) -> None:
        super().__init__(key)
        self.label = label

    def estimate(self, width: int, m: Measurer) -> int:
        return 18 + 16 + 18

    def measure(self, width: int, m: Measurer) -> int:
        self.warm = True
        return 18 + 16 + 18

    def paint(self, p: QPainter, x: int, y: int, w: int, st: PaintState) -> None:
        f = st.m.font(theme.FS_MICRO)
        tw = st.m.text_w(self.label, f)
        cy = y + 18 + 8
        hair = theme.blend(st.t.hair, st.t.canvas)
        left_w = int((w - tw - 24) / 2)
        hline(p, x, cy, left_w, hair)
        hline(p, x + w - left_w, cy, left_w, hair)
        st.m.draw_text(p, x + (w - tw) / 2, y + 18 + (16 - st.m.line_h(f)) / 2, self.label, f, QColor(st.t.text_3))

    def text(self) -> str:
        return self.label


def compact_label(it: CompactItem) -> str:
    text = "Conversation compacted" + ("" if it.trigger == "manual" else " automatically")
    if it.pre_tokens:
        text += f" · {tokens(it.pre_tokens)} → {tokens(it.post_tokens) if it.post_tokens else 'summary'}"
    return text


# ---------------------------------------------------------------- notices


def notice_mode(it: NoticeItem) -> str:
    if it.tag in ("divider", "interrupt"):
        return "divider"
    if it.tag in ("task", "retry-ok", "cli-info"):
        return str(it.tag)
    return "notice"


class NoticeBlock(NodeBlock):
    KIND = "notice"
    __slots__ = ("item", "open")

    def __init__(self, item: NoticeItem) -> None:
        self.item = item
        self.open = False
        mode = notice_mode(item)
        pad = (0, 10, 0, 10) if mode in ("notice", "task") else (0, 6, 0, 6)
        super().__init__(f"notice:{item.id}", self._build, pad, est_h=40)
        self.on("more", self._toggle)
        self.sync(item)

    def sync(self, item: NoticeItem) -> bool:
        changed = item.rev != self.rev
        self.item = item
        self.rev = item.rev
        self.sig = (item.rev, self.open)
        if changed:
            self.rebuild()
        return changed

    def _toggle(self, _t: Target, view: Any) -> None:
        self.open = not self.open
        self.sig = (self.item.rev, self.open)
        self.rebuild()
        view.remeasure(self)

    def _build(self, m: Measurer) -> nd.Node:
        it = self.item
        mode = notice_mode(it)
        t = m.tokens
        if mode == "cli-info":
            first = re.split(r"(?<=\.)\s", it.text)[0]
            body = (
                nd.Markdown(it.text, compact=True, quiet=True)
                if self.open
                else nd.Text(first, theme.FS_SMALL, 400, "text_3", wrap=True, line_h=19)
            )
            more = (
                nd.Button("Less" if self.open else "More", "more", kind="link") if len(it.text) > len(first) else None
            )
            return nd.hstack(
                nd.Icon("info", "text_3", 12), nd.vstack(body, more, spacing=2), spacing=8, stretch=[1], valign="top"
            )
        if mode in ("task", "retry-ok"):
            warn = it.level == "warning"
            icon = ("circle-alert" if warn else "circle-check") if mode == "task" else "info"
            color = ("accent_text" if warn else "ok") if mode == "task" else "text_3"
            return nd.hstack(
                nd.Icon(icon, color, 12),
                nd.Text(it.text, theme.FS_SMALL, 400, "text_3", wrap=True, line_h=19),
                spacing=8,
                stretch=[1],
                valign="top",
            )
        # a notice on a wash
        bg = t.err_wash if it.level == "error" else t.accent_wash if it.level == "warning" else t.fill_1
        icon = "circle-alert" if it.level == "error" else "triangle-alert" if it.level == "warning" else "info"
        color = "err" if it.level == "error" else "accent_text" if it.level == "warning" else "text_3"
        count = f' <span style="color:{t.text_3}">×{it.count}</span>' if it.count and it.count > 1 else ""
        text = nd.Text(
            f'<p style="margin:0;line-height:20px">{html.escape(it.text)}{count}</p>',
            theme.FS_UI,
            400,
            "text",
            wrap=True,
            html=True,
        )
        col = nd.vstack(text, spacing=2)
        if it.detail:
            if self.open:
                col.add(
                    nd.Surface(
                        nd.Text(
                            f'<div style="white-space:pre-wrap;line-height:19px">{html.escape(it.detail)}</div>',
                            12,
                            400,
                            "text_2",
                            mono=True,
                            html=True,
                        ),
                        "inset",
                        None,
                        theme.R2,
                        (10, 8, 10, 8),
                    )
                )
            col.add(nd.Button("Hide details" if self.open else "Details", "more", kind="link"))
        inner = nd.hstack(nd.Icon(icon, color, 14), col, spacing=10, stretch=[1], valign="top")
        # the wash is painted by a Surface with a blended colour name: resolve here
        surf = nd.Surface(inner, None, None, theme.R3, (14, 10, 14, 10))
        return _Washed(surf, theme.blend(bg, t.canvas))

    def text(self) -> str:
        return self.item.text


class _Washed(nd.Node):
    """A surface painted on a given colour (the notice washes are blends, not tokens)."""

    __slots__ = ("child", "color")

    def __init__(self, child: nd.Node, color: QColor) -> None:
        super().__init__()
        self.child, self.color = child, color

    def layout(self, x: int, y: int, w: int, m: Measurer) -> int:
        self.x, self.y, self.w = x, y, w
        self.h = self.child.layout(x, y, w, m)
        return self.h

    def shift(self, dx: int, dy: int) -> None:
        super().shift(dx, dy)
        self.child.shift(dx, dy)

    def paint(self, p: QPainter, ox: int, oy: int, st: PaintState) -> None:
        rounded(p, QRect(ox + self.x, oy + self.y, self.w, self.h), self.color, None, theme.R3)
        self.child.paint(p, ox, oy, st)

    def hit(self, x: int, y: int):
        return self.child.hit(x, y)

    def targets(self):
        return self.child.targets()

    def text(self) -> str:
        return self.child.text()

    def cool(self) -> None:
        self.child.cool()


# ---------------------------------------------------------------- command output


class CommandOutputBlock(NodeBlock):
    KIND = "command-output"
    __slots__ = ("item", "cwd")

    def __init__(self, item: CommandOutputItem, cwd: str) -> None:
        self.item = item
        self.cwd = cwd
        super().__init__(f"cmd:{item.id}", self._build, (0, 10, 0, 10), est_h=80)
        self.sync(item)

    def sync(self, item: CommandOutputItem) -> bool:
        changed = item.rev != self.rev
        self.item = item
        self.rev = item.rev
        self.sig = (item.rev,)
        if changed:
            self.rebuild()
        return changed

    def _build(self, m: Measurer) -> nd.Node:
        head = nd.hstack(
            nd.Icon("square-terminal", "text_3", 12),
            nd.Text("Command output", theme.FS_MICRO, 600, "text_3", wrap=False),
            spacing=6,
        )
        body = nd.Markdown(self.item.text, compact=True, cwd=self.cwd)
        inner = nd.vstack(head, body, spacing=6)
        return _Washed(
            nd.Surface(inner, None, None, theme.R3, (14, 10, 14, 10)), theme.blend(m.tokens.fill_1, m.tokens.canvas)
        )

    def text(self) -> str:
        return self.item.text


# ---------------------------------------------------------------- the turn's footer


class ResultBlock(Block):
    """✱ duration · tokens · cost; the detail and "Fork from here" show while the pointer is on the row."""

    KIND = "result"
    __slots__ = ("item", "sid", "_fork_rect")

    def __init__(self, item: ResultItem, sid: str) -> None:
        super().__init__(f"result:{item.id}")
        self.item = item
        self.sid = sid
        self._fork_rect = QRect()
        self.sync(item)

    def sync(self, item: ResultItem) -> bool:
        changed = item.rev != self.rev
        self.item = item
        self.rev = item.rev
        self.sig = (item.rev,)
        return changed

    def estimate(self, width: int, m: Measurer) -> int:
        return 8 + 20 + 20

    def measure(self, width: int, m: Measurer) -> int:
        self.warm = True
        return 8 + 20 + 20

    def _detail(self) -> str:
        it = self.item
        parts = []
        if it.output_tokens:
            parts.append(f"{tokens(it.output_tokens)} tokens")
        if it.cost_usd:
            parts.append(cost(it.cost_usd))
        return " · ".join(parts)

    def paint(self, p: QPainter, x: int, y: int, w: int, st: PaintState) -> None:
        it = self.item
        t = st.t
        f = st.m.font(theme.FS_MICRO)
        cy = y + 8
        fm = st.m.font(12)
        st.m.draw_text(p, x, cy + (20 - st.m.line_h(fm)) / 2, "✱", fm, QColor(t.accent))
        cx = x + 14
        dur = duration(it.duration_ms)
        st.m.draw_text(p, cx, cy + (20 - st.m.line_h(f)) / 2, dur, f, QColor(t.text_3))
        cx += st.m.text_w(dur, f) + 8
        hovered = st.hover is not None
        if hovered:
            d = self._detail()
            if d:
                st.m.draw_text(p, cx, cy + (20 - st.m.line_h(f)) / 2, d, f, QColor(t.text_3))
                cx += st.m.text_w(d, f) + 8
            if it.chain_uuid:
                on = st.hover.kind == "button"
                color = QColor(t.text if on else t.text_3)
                p.drawPixmap(int(cx), cy + 4, st.m.icon("git-fork", color, 12))
                label = "Fork from here"
                st.m.draw_text(p, cx + 16, cy + (20 - st.m.line_h(f)) / 2, label, f, color)
                lw = st.m.text_w(label, f)
                self._fork_rect = QRect(int(cx - x), 8, int(16 + lw), 20)

    def hit(self, x: int, y: int) -> Optional[Target]:
        if self.item.chain_uuid and self._fork_rect.contains(x, y):
            return Target(
                "button",
                "fork",
                (self._fork_rect.x(), self._fork_rect.y(), self._fork_rect.width(), self._fork_rect.height()),
            )
        return Target("row", "result", (0, 0, self.h_width or 0, self.h))

    def cursor_for(self, target: Target) -> Optional[Any]:
        return Qt.CursorShape.PointingHandCursor if target.kind == "button" else None

    def tooltip_for(self, target: Target) -> str:
        if target.kind == "button":
            return "Start a new session that continues from this point"
        it = self.item
        tip = duration(it.duration_ms)
        if it.output_tokens:
            tip += f" · {tokens(it.output_tokens)} tokens out"
        if it.input_tokens:
            tip += f" · {tokens(it.input_tokens)} in"
        if it.cost_usd:
            tip += f" · {cost(it.cost_usd)}"
        return tip

    def activate(self, target: Target, view: Any) -> None:
        if target.kind == "button":
            store.fork_session(self.sid, self.item.chain_uuid)

    def text(self) -> str:
        return ""


def result_notice(it: ResultItem) -> NoticeItem:
    text = (
        "Stopped: reached the turn limit"
        if it.subtype == "error_max_turns"
        else "Stopped: reached the budget limit"
        if it.subtype == "error_max_budget_usd"
        else it.text or "The turn ended with an error"
    )
    return NoticeItem(
        id=it.id, level="error", text=text, detail="\n".join(it.errors) if it.errors else None, rev=it.rev
    )


# ---------------------------------------------------------------- the working line


class WorkingBlock(Block):
    """The breathing mark, a verb from the composing room, elapsed time and thinking tokens, while a
    turn runs and no fold on the page carries the mark."""

    KIND = "working"
    __slots__ = ("sid", "verb", "start_ts", "shown", "status", "compacting", "thinking_tokens", "_t0")

    def __init__(self, sid: str) -> None:
        super().__init__("working")
        self.sid = sid
        self.verb = random.choice(VERBS)
        self.start_ts = 0.0
        self.shown = False
        self.status = ""
        self.compacting = False
        self.thinking_tokens = 0
        self._t0 = time.monotonic()

    def sync(self, start_ts: float, quiet: bool) -> bool:
        r = store.rt.get(self.sid)
        status = r.status if r else ""
        compacting = bool(r and r.st.get("compacting"))
        shown = status in ("running", "starting") and (not quiet or compacting)
        sig = (shown, status, compacting, int(start_ts))
        changed = sig != self.sig
        self.sig = sig
        self.shown, self.status, self.compacting, self.start_ts = shown, status, compacting, start_ts
        self.thinking_tokens = int(r.thinking_tokens) if r else 0
        return changed

    def estimate(self, width: int, m: Measurer) -> int:
        return 10 + 30 + 4 if self.shown else 0

    def measure(self, width: int, m: Measurer) -> int:
        self.warm = True
        return 10 + 30 + 4 if self.shown else 0

    def paint(self, p: QPainter, x: int, y: int, w: int, st: PaintState) -> None:
        if not self.shown:
            return
        t = st.t
        cy = y + 10
        draw_mark(p, QRectF(x, cy + 7, 15, 15), t, 0.55 + 0.45 * (0.5 - 0.5 * _cos((st.now - self._t0) % 1.8 / 1.8)))
        f = st.m.font(theme.FS_UI, 500)
        text = (
            "Compacting the conversation"
            if self.compacting
            else "Starting Claude Code"
            if self.status == "starting"
            else f"{self.verb}…"
        )
        st.m.draw_text(p, x + 25, cy + (30 - st.m.line_h(f)) / 2, text, f, QColor(t.text_3))
        cx = x + 25 + st.m.text_w(text, f) + 10
        elapsed = time.time() * 1000 - self.start_ts if self.start_ts else 0
        meta = duration(elapsed) if elapsed > 1000 else ""
        if self.thinking_tokens:
            meta += f"{' · ' if meta else ''}{tokens(self.thinking_tokens)} thinking tokens"
        if meta:
            f2 = st.m.font(theme.FS_SMALL)
            st.m.draw_text(p, cx, cy + (30 - st.m.line_h(f2)) / 2, meta, f2, QColor(t.text_3))

    def live(self) -> bool:
        return self.shown

    def tick(self, now: float) -> Optional[Tuple[int, int, int, int]]:
        return (0, 0, 100000, self.h) if self.shown else None

    @property
    def static(self) -> bool:
        return False


def _cos(phase: float) -> float:
    import math

    return math.cos(phase * 2 * math.pi)


def draw_mark(p: QPainter, r: QRectF, t: theme.Tokens, bowl_alpha: float = 1.0, ink: Optional[str] = None) -> None:
    """The pilcrow ¶ from the brand SVG (viewBox 4.5 4 14 16)."""
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    s = r.height() / 16.0
    x0, y0 = r.x() - 4.5 * s, r.y() - 4 * s
    bowl = QColor(t.accent)
    bowl.setAlphaF(bowl_alpha)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(bowl)
    p.drawEllipse(QPointF(x0 + 10.6 * s, y0 + 9.2 * s), 4.1 * s, 4.1 * s)
    p.setBrush(QColor(ink or t.text_2))
    rx = 0.5 * s
    p.drawRoundedRect(QRectF(x0 + 10.6 * s, y0 + 5.1 * s, 6.6 * s, 1.9 * s), rx, rx)
    p.drawRoundedRect(QRectF(x0 + 12.4 * s, y0 + 5.1 * s, 1.9 * s, 13.8 * s), rx, rx)
    p.drawRoundedRect(QRectF(x0 + 15.3 * s, y0 + 5.1 * s, 1.9 * s, 13.8 * s), rx, rx)


# ---------------------------------------------------------------- the loading skeleton


class SkeletonBlock(Block):
    KIND = "skeleton"
    __slots__ = ("shown",)

    def __init__(self) -> None:
        super().__init__("skeleton")
        self.shown = True

    def estimate(self, width: int, m: Measurer) -> int:
        return 6 + 14 * 3 + 10 * 2 if self.shown else 0

    measure = estimate

    def paint(self, p: QPainter, x: int, y: int, w: int, st: PaintState) -> None:
        if not self.shown:
            return
        c = theme.blend(st.t.fill_1, st.t.canvas)
        cy = y + 6
        for short in (False, True, False):
            rounded(p, QRect(x, cy, min(w, 260) if short else w, 14), c, None, theme.R2)
            cy += 24

    @property
    def static(self) -> bool:
        return True


class GapBlock(Block):
    """Empty room (the pads between units that the web's margins made)."""

    KIND = "gap"
    __slots__ = ("gap",)

    def __init__(self, key: str, gap: int) -> None:
        super().__init__(key)
        self.gap = gap
        self.h = gap

    def estimate(self, width: int, m: Measurer) -> int:
        return self.gap

    measure = estimate


__all__ = [
    "CommandOutputBlock",
    "DividerBlock",
    "GapBlock",
    "NoticeBlock",
    "ResultBlock",
    "SkeletonBlock",
    "WorkingBlock",
    "compact_label",
    "draw_mark",
    "result_notice",
]

_ = (Callable,)
PILCROW_EOF_d3844fbd4f
  wrote=$((wrote + 1))
  # ---- qt/pilcrow_qt/canvas/blocks/note.py (14265 bytes)
  cat > "$D"/'qt/pilcrow_qt/canvas/blocks/note.py' <<'PILCROW_EOF_50a6e5bb10'
"""Messages Pilcrow writes into a conversation, drawn in the tool cards' grammar (HELPERS.md §6.1).

A note to a lead — a helper finished, failed, was stopped or needs the person — is a card like any
tool's: a state dot in the status column, "Helper finished" as the verb, the helper's name as the
target, its figures at the right, Open on hover, and the handoff in an inset well under the head that
folds like a tool body. A brief or a message from the lead in a helper's conversation is the same card
with "From the lead" as the verb and the lead's title as the target; the standing instructions every
helper gets are folded under the brief, since they are for the model.
"""

from __future__ import annotations

import re
from typing import Any, Dict, List, Optional, Tuple

from PySide6.QtCore import QRect, QRectF, Qt
from PySide6.QtGui import QColor, QPainter, QPen

from ... import theme
from ...lib.tools_meta import HELPER_HEADER_PREFIX, HELPER_RING, HELPER_TONE
from ...lib.transcript_model import UserItem
from ...store import store
from .. import nodes as nd
from ..paint import Measurer, PaintState, rounded
from ..scene import Group, Target
from .base import NodeBlock, chevron, paint_head_tint

NOTE_RE = re.compile(r"<helper-note\s+([^>]*)>\n?(.*?)\n?</helper-note>", re.S)
ATTR_RE = re.compile(r'(\w+)="([^"]*)"')
HEAD_H = 28
VERBS = {
    "done": "Helper finished",
    "failed": "Helper failed",
    "stopped": "Helper stopped",
    "needs_action": "Helper needs you",
    "skipped": "Helper skipped",
    "running": "Helper",
}
MetaPart = Tuple[str, str, Any]


def parse_notes(text: str) -> Tuple[List[Dict[str, str]], str]:
    """The ``<helper-note>`` blocks of a note (their attributes and body) and the text around them."""
    parts: List[Dict[str, str]] = []
    tail: List[str] = []
    last = 0
    for m in NOTE_RE.finditer(text):
        before = text[last : m.start()].strip()
        if before:
            tail.append(before)
        attrs = dict(ATTR_RE.findall(m.group(1)))
        attrs["body"] = m.group(2).strip()
        parts.append(attrs)
        last = m.end()
    rest = text[last:].strip()
    if rest:
        tail.append(rest)
    return parts, " ".join(tail)


def _cwd_of(sid: str) -> str:
    rt = store.rt.get(sid)
    return str((rt.st.get("cwd") if rt else "") or "")


def _well(text: str, cwd: str) -> nd.Node:
    """Prose from another session, on the inset well a tool's result sits on."""
    return nd.Surface(nd.Markdown(text, compact=True, cwd=cwd), "inset", "light:hair", theme.R3, (12, 10, 12, 10))


# ---------------------------------------------------------------- the head, as a tool card draws it


def _meta_width(st: PaintState, parts: List[MetaPart]) -> int:
    w = 0
    for kind, text, _tone in parts:
        if kind == "mono":
            w += int(st.m.text_w(text, st.m.font(11.5, 400, True))) + 5
        else:
            w += int(st.m.text_w(text, st.m.font(theme.FS_MICRO))) + 8
    return w


def _paint_meta(p: QPainter, right: int, y: int, head_h: int, st: PaintState, parts: List[MetaPart]) -> None:
    x = right
    for kind, text, tone in reversed(parts):
        if kind == "mono":
            f = st.m.font(11.5, 400, True)
            tw = st.m.text_w(text, f)
            x -= tw
            st.m.draw_text(p, x, y + (head_h - st.m.line_h(f)) / 2, text, f, QColor(tone))
            x -= 5
        else:
            f = st.m.font(theme.FS_MICRO)
            tw = st.m.text_w(text, f)
            x -= tw
            st.m.draw_text(p, x, y + (head_h - st.m.line_h(f)) / 2, text, f, QColor(tone))
            x -= 8


def paint_card_head(
    p: QPainter,
    x: int,
    y: int,
    w: int,
    head_h: int,
    st: PaintState,
    *,
    verb: str,
    target: str,
    meta: List[MetaPart],
    reveal: float,
    hover: bool,
    hover_open: bool,
    rects: Dict[str, QRect],
    dot: Optional[str] = None,
    icon: Optional[str] = None,
) -> None:
    """A tool card's head: the status column (a state dot or an icon), the verb in text-3, the target,
    the chevron, an open arrow on hover, the figures right-aligned. ``rects`` receives the arrow's
    rectangle in block coordinates for hit testing."""
    t = st.t
    if hover:
        paint_head_tint(p, QRect(x - 6, y, w + 6, head_h), st)
    icon_y = y + (head_h - 14) // 2
    if dot is not None:
        color = QColor(getattr(t, HELPER_TONE.get(dot, "text_4")))
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(x + 2 + 2.5, icon_y + 2.5, 9, 9)
        if dot in HELPER_RING:
            p.setPen(QPen(color, 1.5))
            p.setBrush(Qt.BrushStyle.NoBrush)
        else:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(color)
        p.drawEllipse(r)
    elif icon:
        p.drawPixmap(x + 2, icon_y, st.m.icon(icon, QColor(t.text_2), 14))
    cx = x + 28
    fv = st.m.font(theme.FS_UI)
    if verb:
        st.m.draw_text(p, cx, y + (head_h - st.m.line_h(fv)) / 2, verb, fv, QColor(t.text_3))
        cx += st.m.text_w(verb, fv) + 7
    meta_w = _meta_width(st, meta)
    chev_w = 13 + 7
    open_w = 13 + 7
    avail = max(40, (x + w) - cx - meta_w - chev_w - open_w - 8)
    shown = st.m.elide(target, fv, int(avail))
    st.m.draw_text(p, cx, y + (head_h - st.m.line_h(fv)) / 2, shown, fv, QColor(t.text))
    cx += st.m.text_w(shown, fv) + 7
    chevron(
        p, int(cx), y + (head_h - 13) // 2, 13, reveal, QColor(t.text_3), st, 1.0 if (hover or reveal > 0) else 0.45
    )
    cx += chev_w
    rects["open"] = QRect(int(cx) - x - 4, (head_h - 22) // 2, 22, 22)
    if hover or hover_open:
        if hover_open:
            rounded(
                p, QRect(int(cx) - 4, y + (head_h - 22) // 2, 22, 22), theme.blend(t.fill_2, t.canvas), None, theme.R2
            )
        p.drawPixmap(
            int(cx), y + (head_h - 13) // 2, st.m.icon("arrow-up-right", QColor(t.text if hover_open else t.text_3), 13)
        )
    _paint_meta(p, x + w, y, head_h, st, meta)


class _Card(Group):
    """A card with a tool-shaped head over one body block; the head folds the body."""

    CHILD_INDENT = 28
    MT = 12
    MB = 12
    __slots__ = ("sid", "body", "user_open", "_rects")

    def __init__(self, key: str, sid: str, has_body: bool) -> None:
        super().__init__(key, head_h=HEAD_H, pad_top=4 if has_body else 0, pad_bottom=10 if has_body else 0, open_=True)
        self.sid = sid
        self.user_open: Optional[bool] = None
        self._rects: Dict[str, QRect] = {}
        self.body = NodeBlock(f"{key}:body", self._build, (0, 0, 0, 0), est_h=60)
        self.shaped = True
        if has_body:
            self.append(self.body)

    # what a subclass says
    def _build(self, m: Measurer) -> nd.Node:  # pragma: no cover - abstract
        raise NotImplementedError

    def head(self) -> Dict[str, Any]:  # pragma: no cover - abstract
        raise NotImplementedError

    def open_target(self) -> Optional[str]:
        return None

    def open_tip(self) -> str:
        return "Open"

    # ---- paint and hits
    def paint(self, p: QPainter, x: int, y: int, w: int, st: PaintState) -> None:
        hover = st.hover is not None and st.hover.kind in ("head", "button")
        hover_open = st.hover is not None and st.hover.kind == "button" and st.hover.id == "open"
        paint_card_head(
            p,
            x,
            y,
            w,
            self.head_h,
            st,
            reveal=self.reveal,
            hover=hover,
            hover_open=hover_open,
            rects=self._rects,
            **self.head(),
        )

    def hit(self, x: int, y: int) -> Optional[Target]:
        if y >= self.head_h:
            return None
        r = self._rects.get("open")
        if r is not None and r.contains(x, y) and self.open_target():
            return Target("button", "open", (r.x(), r.y(), r.width(), r.height()))
        return Target("head", "card", (0, 0, self.h_width or 0, self.head_h))

    def cursor_for(self, target: Target) -> Optional[Any]:
        return Qt.CursorShape.PointingHandCursor

    def tooltip_for(self, target: Target) -> str:
        return self.open_tip() if target.kind == "button" else ""

    def activate(self, target: Target, view: Any) -> None:
        if target.kind == "button" and target.id == "open":
            sid = self.open_target()
            if sid:
                store.open_session(sid)
            return
        if target.kind == "head" and self.children:
            self.user_open = not self.open
            view.toggle_group(self, self.user_open)

    def live(self) -> bool:
        return False


# ---------------------------------------------------------------- a helper's note to its lead


class NoteCard(_Card):
    KIND = "note-card"
    __slots__ = ("part",)

    def __init__(self, key: str, part: Dict[str, str], sid: str) -> None:
        self.part = part
        super().__init__(key, sid, has_body=bool((part.get("body") or "").strip()))

    def _build(self, m: Measurer) -> nd.Node:
        return _well((self.part.get("body") or "").strip(), _cwd_of(self.sid))

    def head(self) -> Dict[str, Any]:
        part = self.part
        state = str(part.get("state") or "")
        meta: List[MetaPart] = []
        t = theme.tokens()
        for key in ("elapsed", "cost"):
            if part.get(key):
                meta.append(("text", str(part[key]), t.text_3))
        files = str(part.get("files") or "")
        if files and files != "0":
            if str(part.get("add") or "0") != "0":
                meta.append(("mono", f"+{part.get('add')}", t.ok))
            if str(part.get("del") or "0") != "0":
                meta.append(("mono", f"−{part.get('del')}", t.err))
        return {
            "dot": state or "stopped",
            "verb": VERBS.get(state, "Helper"),
            "target": str(part.get("name") or ""),
            "meta": meta,
        }

    def open_target(self) -> Optional[str]:
        rt = store.rt.get(self.sid)
        helpers = (rt.st.get("helpers") if rt else None) or []
        name = self.part.get("name")
        return next(
            (str(h.get("id")) for h in helpers if isinstance(h, dict) and h.get("name") == name and h.get("id")), None
        )

    def open_tip(self) -> str:
        return "Open the helper's session"

    def text(self) -> str:
        h = self.head()
        body = (self.part.get("body") or "").strip()
        return f"{h['verb']} {h['target']}" + (f"\n{body}" if body else "")


class NoteBlock(Group):
    """One note message: a card per helper it speaks of (a note coalesces what happened within a
    couple of seconds). The text around the cards is for the model and is not drawn."""

    KIND = "note"
    __slots__ = ("item", "sid", "cards")

    def __init__(self, item: UserItem, sid: str) -> None:
        super().__init__(f"note:{item.id}", head_h=0, pad_top=0, pad_bottom=0, open_=True)
        self.item = item
        self.sid = sid
        self.cards: List[NoteCard] = []
        self.shaped = True
        self.sig = None
        self.sync(item)

    def sync(self, item: UserItem) -> bool:
        changed = item.rev != self.sig
        self.item = item
        self.sig = item.rev
        self.rev = item.rev
        if not changed:
            return False
        parts, _tail = parse_notes(item.text)
        if not parts:
            parts = [{"name": "note", "state": "", "body": item.text}]
        while self.children:
            self.remove(len(self.children) - 1)
        self.cards = [NoteCard(f"note:{item.id}:{k}", part, self.sid) for k, part in enumerate(parts)]
        for c in self.cards:
            self.append(c)
        return True

    def text(self) -> str:
        return "\n\n".join(c.text() for c in self.cards)

    def live(self) -> bool:
        return False


# ---------------------------------------------------------------- the lead's words in a helper's conversation


class FromLeadBlock(_Card):
    """A brief or a message the lead sent (``_from: lead``), drawn as a card rather than as the
    person's bubble: it is not the person speaking. The standing instructions a brief opens with
    fold under it."""

    KIND = "from-lead"
    __slots__ = ("item", "state")

    def __init__(self, item: UserItem, sid: str) -> None:
        self.item = item
