        self.count.setProperty("none", bool(q) and not n)
        self.prev_btn.setEnabled(n > 0)
        self.next_btn.setEnabled(n > 0)
        self._paint_count()

    def _paint_current(self, reveal: bool) -> None:
        needle = self.field.text().strip()
