            fl.addWidget(picker)
        else:
            self.path = line_edit("/path/to/skill", mono=True, name="Folder")
            self.path.textChanged.connect(self._pick)
            browse = button("Browse…", size="sm", on_click=self._browse)
            r = QWidget()
            rl = QHBoxLayout(r)
