            self.on_done()

        def bad(_e: Any) -> None:
            self.busy = False
            self.import_btn.setEnabled(True)

        store.call("skills.import", {"scope": self.scope.value, "cwd": self.cwd, "from": self.from_path}).then(
            ok
        ).catch(bad)
