        self.update()
        super().leaveEvent(e)

    def _colors(self) -> Look:
        """(background, ink, icon opacity, border) for the current state."""
        t = theme.tokens()
        k = self.kind
        hover = self._hover and self.isEnabled()
        if k == "primary":
            if not self.isEnabled():
