  }
  if (learned.length) {
    out += '\n\nThe same work was already done in ' + (learned.length === 1 ? 'one repository' : `${learned.length} repositories`) + '. Follow the same approach where it fits:\n' + learned.map((l) => `- ${l.name}: ${l.summary || 'no summary'}`).join('\n');
  }
