    scheduleId: s.id,
    scheduleName: s.name,
    sessionId: session.id,
    cwd: session.cwd,
    startedAt: entry.startedAt,
    endedAt,
    durationMs: endedAt - entry.startedAt,
    status,
    reason: reason || null,
    summary: lastText.slice(0, 1200),
