// ---------------------------------------------------------------- inbox

export function inboxList() {
  return { items: inbox.items, unread: inbox.items.filter((i) => !i.read).length };
}

export function markRead(ids) {
  for (const i of inbox.items) if (!ids || ids.includes(i.id)) i.read = true;
