const keyOf = (cwd) => crypto.createHash('sha1').update(slash(cwd)).digest('hex').slice(0, 16);
const dirOf = (cwd) => path.join(ROOT, keyOf(cwd));
const stepsFile = (cwd, sid) => path.join(dirOf(cwd), `steps-${sid}.json`);

