function unsuitable(cwd) {
  if (!cwd) return 'no folder';
  const c = slash(path.resolve(cwd));
  if (c === slash(HOME)) return 'home folder';
  if (/^([a-z]:)?\/?$/i.test(c)) return 'root of a drive';
