  const files = [];
  for (const line of ns.stdout.split('\n')) {
    const [a, d, p] = line.split('\t');
    if (p === undefined) continue;
    files.push({ path: p, status: status.get(p) || 'M', add: a === '-' ? 0 : +a, del: d === '-' ? 0 : +d, binary: a === '-' });
