    if (command) args = isPs ? ['-NoLogo', '-Command', command] : isBash ? ['-lc', command] : ['/d', '/s', '/c', command];
    else if (isPs) args = caps.conpty ? ['-NoLogo'] : ['-NoLogo', '-NoExit', '-Command', '-'];
    else if (isBash) args = caps.conpty ? ['--login', '-i'] : ['--login'];
