                )}
                <span className={`ds ${cls}`}>
                  {gutterBtn(l)}
                  {l.t === ' ' ? ' ' : l.t === '-' ? '−' : '+'}
                </span>
                <span className={`dc ${cls} hl-line`} style={st}>{renderContent(l.s, toks.get(l), words.get(l))}</span>
                {commentBlock(l, two ? 4 : numbers ? 3 : 2)}
