  const blocks = useMemo(() => splitBlocks(text), [text]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const pres = Array.from(el.querySelectorAll<HTMLPreElement>('pre.hl:not([data-hl])'));
