          options={[
            { value: 'unified', label: <Rows2 size={13} />, title: 'Unified' },
            { value: 'split', label: <Columns2 size={13} />, title: narrow ? 'Side by side (widen the panel to use it)' : 'Side by side', disabled: narrow },
          ]}
