    const warmest = hs.reduce((best, h) => ((warmth[h.status] || 0) > (warmth[best.status] || 0) ? h : best), s);
    const lead = warmest === s ? s : { ...s, status: warmest.status, pending: Math.max(s.pending || 0, warmest.pending || 0) };
