      const same = old && old.units.length === slice.length && old.units.every((u, i) => u === slice[i]);
      out.push(same ? old : { key: 'pg' + p, units: slice, est: slice.reduce((n, u) => n + EST[u.kind], 0) + 24 * slice.length });
