  py: 'Python', python: 'Python', sh: 'Shell', bash: 'Shell', zsh: 'Shell', shell: 'Shell', console: 'Terminal', json: 'JSON', jsonc: 'JSON', yaml: 'YAML', yml: 'YAML',
