      const text = this.parser.parseInline(token.tokens);
      const href = token.href || '';
      const title = token.title ? ` title="${escape(token.title)}"` : '';
      return `<a href="${escape(href)}"${title} target="_blank" rel="noopener noreferrer">${text}</a>`;
