/** Does an inline `code` span look like a file path (optionally with :line)? */
export function asPathRef(text: string): { path: string; line?: number } | null {
  const t = text.trim();
  if (t.length > 240 || /\s/.test(t)) return null;
  if (/^https?:/i.test(t)) return null;
