    if (parent) return; // a subagent's own prompt; the Agent card already shows it
    const texts: string[] = [];
    const images: string[] = [];
    const files: string[] = [];
    for (const b of content) {
      if (b.type === 'text') {
        const text = b.text || '';
        const af = text.match(/^<attached_file name="([^"]+)">/);
        if (af) files.push(af[1]);
        else texts.push(text);
