  text-overflow: ellipsis;
  white-space: nowrap;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
.tnum {
  font-variant-numeric: tabular-nums;
}
.rot {
  transform: rotate(90deg);
}

/* ---- buttons
   Default buttons are quiet fills; one primary (amber) per surface. Every press gives a 2% squeeze. */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 30px;
  padding: 0 12px;
  border-radius: var(--r-2);
  background: var(--fill-2);
  color: var(--text);
  font-weight: 500;
  white-space: nowrap;
  transition: background var(--t-fast), color var(--t-fast), box-shadow var(--t-fast), transform var(--t-fast) var(--ease), opacity var(--t-fast);
}
.btn:hover {
  background: var(--fill-3);
}
.btn:active:not(:disabled) {
  transform: scale(0.98);
}
.btn:disabled {
  opacity: 0.45;
  cursor: default;
}
.btn.primary:disabled {
  opacity: 1;
  background: var(--fill-2);
  color: var(--text-4);
  box-shadow: none;
}
.btn svg {
  opacity: 0.85;
}
.btn.primary {
  background: var(--accent);
  color: var(--accent-ink);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18), 0 1px 2px rgba(0, 0, 0, 0.18);
}
.btn.primary:hover {
