}
.btn.primary svg {
  opacity: 1;
}
.btn.ghost {
  background: transparent;
  color: var(--text-2);
}
.btn.ghost:hover {
  background: var(--fill-2);
  color: var(--text);
}
.btn.outline {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--hair-2);
}
.btn.outline:hover {
  background: var(--fill-1);
}
.btn.danger {
  color: var(--err);
}
.btn.danger:hover {
  background: var(--err-wash);
}
.btn.danger.solid {
  background: var(--err);
  color: #fff;
}
.btn.danger.solid:hover {
  filter: brightness(1.06);
}
.btn.sm {
  height: 26px;
  padding: 0 10px;
