  border-radius: var(--r-2);
}
.btn.lg {
  height: 36px;
  padding: 0 16px;
  font-size: 13.5px;
  border-radius: var(--r-3);
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-2);
  color: var(--text-3);
  transition: background var(--t-fast), color var(--t-fast), transform var(--t-fast) var(--ease);
  flex: none;
}
.icon-btn:hover {
  background: var(--fill-2);
  color: var(--text);
}
.icon-btn:active {
  transform: scale(0.94);
}
.icon-btn.active,
.icon-btn[aria-expanded='true'] {
  background: var(--fill-2);
  color: var(--text);
}
.icon-btn.sm {
  width: 24px;
  height: 24px;
  border-radius: var(--r-2);
}

.link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--text-2);
  font-size: inherit;
  transition: color var(--t-fast);
}
.link:hover {
  color: var(--text);
}

/* ---- inputs: filled, no visible border until hover/focus */
.input,
.select,
.textarea {
  width: 100%;
  height: 34px;
  padding: 0 11px;
  border-radius: var(--r-2);
  border: none;
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
  color: var(--text);
  outline: none;
  transition: box-shadow var(--t-fast), background var(--t-fast);
}
.input::placeholder,
.textarea::placeholder {
