}
.switch.on::after {
  transform: translateX(14px);
}
[data-theme='dark'] .switch:not(.on) {
  background: #3a3a3e;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 19px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 11px;
